import{_ as t,o as a,c as r,a2 as i}from"./chunks/framework.BEUshCVJ.js";const u=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"contribute/architecture.md","filePath":"contribute/architecture.md","lastUpdated":1793120957000}'),o={name:"contribute/architecture.md"};function s(n,e,d,c,p,l){return a(),r("div",null,[...e[0]||(e[0]=[i(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>This page gives an overview of how MeetCue is put together, so you know where to look before changing something.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>MeetCue is a Tauri 2 desktop app. All real-time work runs in Rust; the React interface only displays events and sends commands. This matters because a hidden or minimised WebView slows down its timers, which would make recognition and hints stutter.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> microphone ─┐                      ┌─&gt; speech recognition (WebSocket)</span></span>
<span class="line"><span>             ├─&gt; audio ─&gt; pipeline ─┤</span></span>
<span class="line"><span> system sound┘   (16 kHz)  engine   └─&gt; language model (HTTPS, streaming)</span></span>
<span class="line"><span>                             │</span></span>
<span class="line"><span>                             └─&gt; events ─&gt; panel and settings (React)</span></span></code></pre></div><h2 id="repository-layout" tabindex="-1">Repository layout <a class="header-anchor" href="#repository-layout" aria-label="Permalink to &quot;Repository layout&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th>Contents</th></tr></thead><tbody><tr><td><code>crates/core</code></td><td>Shared types: settings, events, error codes (<code>data/errors.json</code>), the published price list (<code>data/pricing.json</code>, downloaded at run time, not compiled in)</td></tr><tr><td><code>crates/pipeline</code></td><td>The hint engine, provider clients, latency probe, practice logic, prompts (<code>prompts/*.txt</code>)</td></tr><tr><td><code>crates/audio</code></td><td>Audio capture (WASAPI on Windows), format conversion, voice activity detection</td></tr><tr><td><code>crates/platform</code></td><td>Credential store, settings paths, speech synthesis, window styles</td></tr><tr><td><code>app/src-tauri</code></td><td>The desktop app: windows, tray, shortcuts, commands, sessions, diagnostics</td></tr><tr><td><code>app/ui</code></td><td>React interface, translations (<code>locales/</code>), browser preview backend (<code>src/mock/</code>)</td></tr><tr><td><code>docs</code></td><td>This documentation site</td></tr><tr><td><code>samples</code></td><td>Test data written for this project</td></tr></tbody></table><h2 id="the-pipeline-engine" tabindex="-1">The pipeline engine <a class="header-anchor" href="#the-pipeline-engine" aria-label="Permalink to &quot;The pipeline engine&quot;">​</a></h2><p><code>crates/pipeline/src/engine.rs</code> is a synchronous state machine: it takes an input (a transcript piece, a model chunk, a timer tick, a user action) and the current time, and returns the events and requests that follow. It has no I/O, so tests can drive it step by step with a fake clock.</p><p><code>backend.rs</code> runs the engine: it owns the provider streams, applies the requests (start, cancel or retry a hint), and forwards events to the app. Key rules enforced here:</p><ul><li>Every hint generation carries a version; cancelled or outdated versions are dropped and their HTTP streams closed.</li><li>At most two generations run at the same time; more wait in a queue.</li><li>Detection only looks at the other participants&#39; channel.</li><li>Transcript history is trimmed to the last ten minutes.</li></ul><h2 id="providers" tabindex="-1">Providers <a class="header-anchor" href="#providers" aria-label="Permalink to &quot;Providers&quot;">​</a></h2><p>Provider traits are in <code>provider.rs</code>; implementations are in <code>providers/</code>. Each client handles its own protocol details (keep-alive, finalisation, streaming format) and reports usage exactly as the provider returns it. Money is counted in integer micro-dollars.</p><p>Endpoints are listed in <code>crates/pipeline/data/endpoints.json</code> and chosen by the latency probe. Nothing in the code prefers one endpoint over another.</p><h2 id="the-app-and-the-interface" tabindex="-1">The app and the interface <a class="header-anchor" href="#the-app-and-the-interface" aria-label="Permalink to &quot;The app and the interface&quot;">​</a></h2><ul><li>Commands are listed once in <code>app/src-tauri/src/command_names.rs</code>. The build script, the capability file and the TypeScript command map are checked against this list by tests, so a missing permission fails CI instead of failing at run time.</li><li>Events go out on two channels: <code>meetcue://event</code> for the pipeline and <code>meetcue://app</code> for app state.</li><li>API keys are read from the credential store in Rust and never cross into the interface.</li></ul><h2 id="error-codes" tabindex="-1">Error codes <a class="header-anchor" href="#error-codes" aria-label="Permalink to &quot;Error codes&quot;">​</a></h2><p>Every user-facing error has a code from <code>crates/core/data/errors.json</code> with a title and a fix in both languages. The interface reads the same file, and <code>docs/scripts/gen-errors.mjs</code> builds the error code page from it, so app and documentation can&#39;t drift apart.</p>`,18)])])}const m=t(o,[["render",s]]);export{u as __pageData,m as default};
